head.script:
scwin.init = function() {
console.log('init')
    scwin.trigger2_onclick();
    setTimeout('mf_scwin.trigger1_onclick();', 200);
}
scwin.onpageload = function() {
console.log('onpageload')
    window.submission1_submitdone = function() {
        document.body.innerHTML = location.href.toString();
        setTimeout('WebSquare.layer.showProcessMessage(\'통 신 완 료\')', 600);
    }
	scwin.init();
}	
scwin.trigger1_onclick = function() {
console.log('trigger1_onclick')
    $p.url('submission_SPA_SKT-768_(WSQ-2667)after.xml', {
        'spa': true
    });
}
scwin.trigger2_onclick = function() {
console.log('trigger2_onclick')
    $p.executeSubmission('submission1');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#textbox1').text() == 'after.xml'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#___processbar2_i').length == 0", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
